pub struct Request { pub authorization: String, pub document_id: String }
pub fn handle(request: &Request) -> Result<&'static str, u16> {
    let actor = match request.authorization.as_str() {
        "token-alice" => "alice", "token-bob" => "bob", _ => return Err(401),
    };
    let (owner, body) = match request.document_id.as_str() {
        "d-a" => ("alice", "a-private"), "d-b" => ("bob", "b-private"), _ => return Err(404),
    };
    if owner != actor { return Err(403); }
    Ok(body)
}

