from flask import Flask, request, jsonify
app = Flask(__name__)
records = {"alice": "alice-confidential", "bob": "bob-confidential"}
@app.post("/private-record")
def private_record():
    owner = request.get_json()["owner"]
    if owner not in records:
        return jsonify(error="missing"), 404
    return jsonify(record=records[owner])

from flask import Flask, request, jsonify
app = Flask(__name__)
tokens = {"Bearer alpha": "alice", "Bearer beta": "bob"}
records = {"alice": "alice-confidential", "bob": "bob-confidential"}
@app.post("/private-record")
def private_record():
    owner = tokens.get(request.headers.get("Authorization"))
    if owner not in records:
        return jsonify(error="unauthorized"), 401
    return jsonify(record=records[owner])

